package nettrace

import (
	"encoding/binary"
	"errors"
	"fmt"
	"net/netip"
)

// IP_STATUS values from ipexport.h (Windows SDK), spelled out so the mapping
// builds and is tested on every platform.
const (
	ipSuccess             = 0     // IP_SUCCESS
	ipDestNetUnreachable  = 11002 // IP_DEST_NET_UNREACHABLE
	ipDestHostUnreachable = 11003 // IP_DEST_HOST_UNREACHABLE
	ipDestProtUnreachable = 11004 // IP_DEST_PROT_UNREACHABLE
	ipDestPortUnreachable = 11005 // IP_DEST_PORT_UNREACHABLE
	ipReqTimedOut         = 11010 // IP_REQ_TIMED_OUT
	ipTTLExpiredTransit   = 11013 // IP_TTL_EXPIRED_TRANSIT
	ipTTLExpiredReassem   = 11014 // IP_TTL_EXPIRED_REASSEM
	ipDestUnreachable     = 11040 // IP_DEST_UNREACHABLE
	ipTimeExceeded        = 11041 // IP_TIME_EXCEEDED
	ipDestScopeMismatch   = 11045 // IP_DEST_SCOPE_MISMATCH
	ipGeneralFailure      = 11050 // IP_GENERAL_FAILURE
)

// originEcho marks a reply built from an ICMP echo status (Windows
// IcmpSendEcho). It is a DevDesk value outside the kernel's
// SO_EE_ORIGIN_* range, so it never collides with originLocal or originICMP.
const originEcho = 0xF0

// echoReplyMinLen is the part of ICMP_ECHO_REPLY this package reads: Address
// (4 bytes, network order) and Status (4 bytes, little-endian).
const echoReplyMinLen = 8

// EchoStatusError reports an ICMP echo status that carries no usable hop.
// Its text is ASCII only, never a localized system message.
type EchoStatusError struct {
	Status uint32
}

func (e *EchoStatusError) Error() string {
	return fmt.Sprintf("ICMP status %d", e.Status)
}

// echoReply builds the reply for an echo status and the address that
// answered (which may be the zero address). A timeout is errSilent; a general
// failure or an unknown status is an *EchoStatusError.
func echoReply(status uint32, from netip.Addr) (reply, error) {
	var icmpType uint8
	switch status {
	case ipSuccess:
		icmpType = 0
	case ipTTLExpiredTransit:
		icmpType = icmpTimeExceeded
	case ipReqTimedOut:
		return reply{}, errSilent
	case ipDestNetUnreachable, ipDestHostUnreachable, ipDestProtUnreachable,
		ipDestPortUnreachable, ipTTLExpiredReassem, ipDestUnreachable,
		ipTimeExceeded, ipDestScopeMismatch:
		// Kept as is: classifyEcho decides what they mean.
	default: // ipGeneralFailure and anything unknown
		return reply{}, &EchoStatusError{Status: status}
	}
	return reply{Addr: from, ICMPType: icmpType, Origin: originEcho, Status: status}, nil
}

// classifyEcho maps an echo-status reply to the kind of hop it reveals.
func classifyEcho(r reply, _ netip.Addr) HopKind {
	switch r.Status {
	case ipSuccess:
		return HopTarget
	case ipTTLExpiredTransit:
		return HopRouter
	case ipDestNetUnreachable, ipDestHostUnreachable,
		ipDestProtUnreachable, ipDestPortUnreachable:
		return HopUnreachable
	}
	return HopError
}

// decodeEchoReply4 reads the address and status from an ICMP_ECHO_REPLY.
func decodeEchoReply4(buf []byte) (netip.Addr, uint32, error) {
	if len(buf) < echoReplyMinLen {
		return netip.Addr{}, 0, errors.New("echo reply too short")
	}
	return netip.AddrFrom4([4]byte(buf[0:4])), binary.LittleEndian.Uint32(buf[4:8]), nil
}

package nettrace

import (
	"encoding/binary"
	"errors"
	"net/netip"
	"time"
)

// Values from the Linux kernel headers (linux/errqueue.h, linux/icmp.h,
// bits/socket.h). They are spelled out here so the decoder builds and is
// tested on every platform.
const (
	// sock_extended_err.ee_origin.
	originLocal = 1 // SO_EE_ORIGIN_LOCAL: the local stack raised the error.
	originICMP  = 2 // SO_EE_ORIGIN_ICMP: an ICMPv4 message arrived.

	// ICMPv4 types and the codes this package cares about.
	icmpDestUnreachable = 3
	icmpTimeExceeded    = 11
	icmpCodePortUnreach = 3

	afInet = 2 // AF_INET

	extendedErrLen = 16 // sizeof(struct sock_extended_err)
	sockaddrInLen  = 16 // sizeof(struct sockaddr_in)
	// Offset of sin_addr inside sockaddr_in: family (2) + port (2).
	sockaddrInAddrOff = 4
)

// reply is one decoded IP_RECVERR error: what answered a probe.
type reply struct {
	Addr     netip.Addr
	ICMPType uint8
	ICMPCode uint8
	Origin   uint8
	Errno    uint32
	// Status is the ICMP echo status, set only when Origin is originEcho.
	Status uint32
	// RTT is left zero by decodeExtendedErr; the caller measures it.
	RTT time.Duration
}

var errShortExtendedErr = errors.New("extended error message too short")
var errNotAFInet = errors.New("extended error offender is not an IPv4 address")

// decodeExtendedErr reads a sock_extended_err followed by the sockaddr_in of
// the offender, in native byte order. Extra trailing bytes are ignored.
func decodeExtendedErr(data []byte) (reply, error) {
	if len(data) < extendedErrLen+sockaddrInLen {
		return reply{}, errShortExtendedErr
	}
	sa := data[extendedErrLen : extendedErrLen+sockaddrInLen]
	if binary.NativeEndian.Uint16(sa[0:2]) != afInet {
		return reply{}, errNotAFInet
	}
	return reply{
		Addr:     netip.AddrFrom4([4]byte(sa[sockaddrInAddrOff : sockaddrInAddrOff+4])),
		ICMPType: data[5],
		ICMPCode: data[6],
		Origin:   data[4],
		Errno:    binary.NativeEndian.Uint32(data[0:4]),
	}, nil
}

// classify maps a reply to the kind of hop it reveals.
//
// Known limit: a Port Unreachable from an address other than target is
// reported as HopUnreachable, so a multi-homed target that answers from
// another of its addresses is not recognized as reached.
func classify(r reply, target netip.Addr) HopKind {
	if r.Origin == originEcho {
		return classifyEcho(r, target)
	}
	if r.Origin == originLocal {
		return HopError // the local stack refused the probe (e.g. EMSGSIZE)
	}
	if r.Origin != originICMP {
		return HopError
	}
	switch r.ICMPType {
	case icmpTimeExceeded:
		return HopRouter
	case icmpDestUnreachable:
		if r.ICMPCode == icmpCodePortUnreach && r.Addr == target {
			return HopTarget
		}
		return HopUnreachable
	}
	return HopError
}

//go:build windows

package nettrace

import "golang.org/x/sys/windows"

// platformNoRouteErrnos are the raw Windows codes for "no route": the Winsock
// ones and the IP Helper ones go-netroute can return.
var platformNoRouteErrnos = []error{
	windows.WSAENETUNREACH,
	windows.WSAEHOSTUNREACH,
	windows.ERROR_NETWORK_UNREACHABLE,
	windows.ERROR_HOST_UNREACHABLE,
}

//go:build !windows

package nettrace

// platformNoRouteErrnos is empty off Windows: the common errnos cover the rest.
var platformNoRouteErrnos []error

