	if originEcho != 0xF0 {
		t.Errorf("originEcho = %#x, want 0xF0", uint8(originEcho))
	}
	if originEcho == originLocal || originEcho == originICMP {
		t.Error("originEcho collides with a kernel origin")
	}
}

